(function (root) {
  "use strict";
  const levels = [
    {name: "Loading Lane", rows: ["#########", "#D..#..o#", "#.#.#.#.#", "#...~...#", "#.#.#.#.#", "#o..#..o#", "#########"]},
    {name: "Greenhouse Loop", rows: ["#########", "#D..#..o#", "#.#.~.#.#", "#o#.#...#", "#.#.~.#.#", "#...#..o#", "#########"]},
    {name: "Evening Annex", rows: ["#########", "#o..#..o#", "#.#.~.#.#", "#...#...#", "###.~.###", "#D..#..o#", "#########"]}
  ];
  const directions = {up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0]};
  const events = {
    start: "Your shift begins with one glow cell.",
    moved: "Moved.",
    wait: "Waited one beat.",
    blocked: "Blocked. No beat spent; try another direction or wait.",
    loaded: "Reloaded at the depot.",
    delivered: "Beacon lit! Return to D for another cell.",
    won: "All three greenhouses are lit. Shift complete!",
    undo: "Last successful action undone."
  };
  function bridgeOpen(state) { return state.turn % 4 < 2; }
  function keyAction(key) {
    const keys = {arrowup: "up", w: "up", arrowdown: "down", s: "down", arrowleft: "left", a: "left", arrowright: "right", d: "right", " ": "wait", u: "undo", backspace: "undo", r: "restart"};
    return keys[String(key).toLowerCase()] || null;
  }
  function createState(levelIndex = 0) {
    if (!Number.isInteger(levelIndex) || levelIndex < 0 || levelIndex >= levels.length) throw new RangeError("Unknown board");
    const rows = levels[levelIndex].rows;
    const y = rows.findIndex(row => row.includes("D"));
    return {levelIndex, x: rows[y].indexOf("D"), y, turn: 0, carrying: true, delivered: [], won: false, lastEvent: "start"};
  }
  function advance(state, action) {
    if (state.won || (!directions[action] && action !== "wait")) return state;
    const rows = levels[state.levelIndex].rows;
    const [dx, dy] = directions[action] || [0, 0];
    const x = state.x + dx, y = state.y + dy;
    const tile = rows[y] && rows[y][x];
    if (!tile || tile === "#" || (action !== "wait" && tile === "~" && !bridgeOpen(state))) {
      return {...state, lastEvent: "blocked"};
    }
    const next = {...state, x, y, turn: state.turn + 1, delivered: [...state.delivered], lastEvent: action === "wait" ? "wait" : "moved"};
    if (tile === "D" && !next.carrying) {
      next.carrying = true;
      next.lastEvent = "loaded";
    }
    const target = `${x},${y}`;
    if (tile === "o" && next.carrying && !next.delivered.includes(target)) {
      next.delivered.push(target);
      next.delivered.sort();
      next.carrying = false;
      next.lastEvent = "delivered";
    }
    const targetCount = rows.join("").split("o").length - 1;
    if (next.delivered.length === targetCount) {
      next.won = true;
      next.lastEvent = "won";
    }
    return next;
  }
  function createController(levelIndex = 0) {
    let state = createState(levelIndex), history = [];
    return {
      get state() { return state; },
      get undoCount() { return history.length; },
      setLevel(index) { state = createState(index); history = []; return state; },
      act(action) {
        if (action === "restart") { state = createState(state.levelIndex); history = []; }
        else if (action === "undo") {
          if (history.length) state = {...history.pop(), lastEvent: "undo"};
        } else {
          const next = advance(state, action);
          if (next.turn !== state.turn) {
            history.push(state);
            if (history.length > 256) history.shift();
          }
          state = next;
        }
        return state;
      }
    };
  }
  function summary(state) {
    return `${events[state.lastEvent]} Position row ${state.y + 1}, column ${state.x + 1}. ${state.delivered.length}/3 beacons lit. ${state.carrying ? "Carrying one cell" : "Empty; reload at D"}. ${state.turn} actions. Next action: beat ${state.turn % 4 + 1}/4, bridge ${bridgeOpen(state) ? "OPEN =" : "CLOSED ×"}.`;
  }
  function mount(doc) {
    const board = doc.getElementById("board");
    const status = doc.getElementById("status");
    const selector = doc.getElementById("level");
    const sound = doc.getElementById("sound");
    const controller = createController();
    let audioContext;
    function tone(event) {
      if (!sound.checked) return;
      const Audio = doc.defaultView.AudioContext || doc.defaultView.webkitAudioContext;
      if (!Audio) return;
      try {
        audioContext = audioContext || new Audio();
        if (audioContext.state === "suspended") audioContext.resume().catch(() => {});
        const frequencies = {blocked: 150, loaded: 440, delivered: 660, won: 880};
        if (!frequencies[event]) return;
        const oscillator = audioContext.createOscillator(), gain = audioContext.createGain();
        oscillator.frequency.value = frequencies[event];
        gain.gain.setValueAtTime(0.03, audioContext.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + 0.12);
        oscillator.connect(gain); gain.connect(audioContext.destination);
        oscillator.start(); oscillator.stop(audioContext.currentTime + 0.13);
      } catch (_) { /* Audio is optional; gameplay and text remain available. */ }
    }
    function render() {
      const state = controller.state, fragment = doc.createDocumentFragment();
      levels[state.levelIndex].rows.forEach((row, y) => Array.from(row).forEach((tile, x) => {
        const cell = doc.createElement("span");
        const delivered = state.delivered.includes(`${x},${y}`);
        const names = {"#": "wall", ".": "path", D: "depot", o: delivered ? "lit beacon" : "unlit beacon", "~": bridgeOpen(state) ? "open bridge" : "closed bridge"};
        cell.className = "tile";
        if (tile === "#") cell.classList.add("wall");
        if (tile === "D") cell.classList.add("depot");
        if (tile === "o") cell.classList.add(delivered ? "delivered" : "target");
        if (tile === "~") {
          cell.classList.add("bridge");
          if (!bridgeOpen(state)) cell.classList.add("closed");
        }
        const player = state.x === x && state.y === y;
        if (player) cell.classList.add("player");
        cell.textContent = {"#": "·", ".": "", D: "D", o: delivered ? "★" : "○", "~": bridgeOpen(state) ? "=" : "×"}[tile];
        cell.setAttribute("aria-label", `Row ${y + 1}, column ${x + 1}: ${names[tile]}${player ? ", courier here" : ""}`);
        fragment.appendChild(cell);
      }));
      board.replaceChildren(fragment);
      status.textContent = summary(state);
    }
    function act(action) {
      const before = controller.state;
      controller.act(action);
      if (controller.state !== before) tone(controller.state.lastEvent);
      render();
    }
    levels.forEach((level, index) => {
      const option = doc.createElement("option");
      option.value = String(index); option.textContent = `${index + 1}. ${level.name}`;
      selector.appendChild(option);
    });
    selector.addEventListener("change", () => { controller.setLevel(Number(selector.value)); render(); board.focus(); });
    doc.getElementById("focus").addEventListener("click", () => board.focus());
    board.addEventListener("keydown", event => {
      const action = keyAction(event.key);
      if (!action || event.altKey || event.ctrlKey || event.metaKey) return;
      event.preventDefault();
      if (!event.repeat) act(action);
    });
    doc.querySelectorAll("[data-action]").forEach(button => button.addEventListener("click", () => { act(button.dataset.action); board.focus(); }));
    render();
    return controller;
  }
  const api = {levels, bridgeOpen, keyAction, createState, advance, createController, summary, mount};
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.MosslightCourier = api;
  if (root.document) root.addEventListener("DOMContentLoaded", () => mount(root.document));
}(typeof globalThis === "object" ? globalThis : this));

"use strict";
(async function main() {
const assert = (await import("node:assert/strict")).default;
const fs = await import("node:fs");
const path = await import("node:path");
const vm = await import("node:vm");
const testDirectory = path.dirname(path.resolve(process.argv[1]));
const source = fs.readFileSync(path.join(testDirectory, "../game/game.js"), "utf8");
const authoredModule = {exports: {}};
vm.compileFunction(source, ["module"])(authoredModule);
const game = authoredModule.exports;
let checks = 0;
function test(name, fn) { fn(); checks += 1; console.log(`PASS ${name}`); }
function solve(levelIndex) {
  const start = game.createState(levelIndex), queue = [{state: start, path: []}];
  const key = s => [s.x, s.y, s.turn % 4, Number(s.carrying), s.delivered.join(";")].join("|");
  const seen = new Set([key(start)]);
  for (let head = 0; head < queue.length; head += 1) {
    const current = queue[head];
    if (current.state.won) return current.path;
    for (const action of ["up", "down", "left", "right", "wait"]) {
      const state = game.advance(current.state, action), id = key(state);
      if (seen.has(id)) continue;
      seen.add(id); queue.push({state, path: current.path.concat(action)});
    }
  }
  throw new Error(`Unsolvable board ${levelIndex}`);
}
test("fixed maps have one depot, three targets, and valid dimensions", () => {
  game.levels.forEach(level => {
    assert.equal(level.rows.length, 7);
    level.rows.forEach(row => { assert.equal(row.length, 9); assert.match(row, /^[#.Do~]+$/); });
    assert.equal(level.rows.join("").split("D").length - 1, 1);
    assert.equal(level.rows.join("").split("o").length - 1, 3);
  });
});
test("wall collisions and unknown actions do not spend a beat", () => {
  const start = game.createState();
  assert.equal(game.advance(start, "left").turn, 0);
  assert.equal(game.advance(start, "left").x, start.x);
  assert.equal(game.advance(start, "not-an-action"), start);
});
test("bridge gate checks the pre-action phase", () => {
  const state = {...game.createState(), x: 3, y: 3, turn: 2};
  assert.equal(game.advance(state, "right").x, 3);
  const entered = game.advance({...state, turn: 1}, "right");
  assert.equal(entered.x, 4); assert.equal(entered.turn, 2);
  assert.equal(game.bridgeOpen(entered), false);
  assert.equal(game.advance(entered, "right").x, 5);
});
test("waiting cycles the phase and keeps position", () => {
  let state = game.createState();
  for (let i = 0; i < 4; i += 1) state = game.advance(state, "wait");
  assert.equal(state.x, 1); assert.equal(state.y, 1);
  assert.equal(state.turn, 4); assert.equal(game.bridgeOpen(state), true);
});
test("depot reload and delivery are single-capacity and immutable", () => {
  const empty = {...game.createState(), x: 2, carrying: false};
  assert.equal(game.advance(empty, "left").carrying, true);
  assert.equal(empty.carrying, false);
  const near = {...game.createState(), x: 1, y: 4};
  const delivered = game.advance(near, "down");
  assert.deepEqual(delivered.delivered, ["1,5"]); assert.equal(delivered.carrying, false);
  assert.deepEqual(near.delivered, []);
  assert.deepEqual(game.advance(delivered, "wait").delivered, ["1,5"]);
});
test("keyboard map includes arrows WASD space undo and restart", () => {
  for (const [key, action] of Object.entries({ArrowUp: "up", W: "up", ArrowDown: "down", s: "down", ArrowLeft: "left", a: "left", ArrowRight: "right", d: "right", " ": "wait", U: "undo", Backspace: "undo", R: "restart"})) {
    assert.equal(game.keyAction(key), action);
  }
  assert.equal(game.keyAction("Tab"), null);
});
test("controller resets, bounds history, and does not record blocked moves", () => {
  const controller = game.createController();
  controller.act("left"); assert.equal(controller.undoCount, 0);
  for (let i = 0; i < 270; i += 1) controller.act("wait");
  assert.equal(controller.undoCount, 256);
  controller.act("undo"); assert.equal(controller.state.turn, 269);
  controller.act("restart"); assert.equal(controller.state.turn, 0); assert.equal(controller.undoCount, 0);
  controller.setLevel(2); assert.equal(controller.state.levelIndex, 2);
  assert.throws(() => game.createState(3), RangeError);
});
game.levels.forEach((level, index) => test(`solver, win lock, and undo-win: ${level.name}`, () => {
  const route = solve(index), controller = game.createController(index);
  route.forEach(action => controller.act(action));
  assert.equal(controller.state.won, true);
  assert.equal(controller.state.delivered.length, 3);
  const count = controller.state.turn;
  controller.act("wait"); assert.equal(controller.state.turn, count);
  controller.act("undo"); assert.equal(controller.state.won, false);
  assert.equal(controller.state.delivered.length, 2);
  assert.match(game.summary(controller.state), /Next action: beat/);
  console.log(`  shortest route: ${route.length} actions`);
}));
test("mounted keyboard/click handlers can play all boards using a DOM test double", () => {
  let doc;
  class Element {
    constructor() {
      this.children = []; this.listeners = {}; this.attributes = {};
      this.dataset = {}; this.checked = false; this.value = "";
      this.classList = {add: () => {}};
    }
    appendChild(child) { this.children.push(child); return child; }
    replaceChildren(fragment) { this.children = [...fragment.children]; }
    setAttribute(name, value) { this.attributes[name] = value; }
    addEventListener(type, listener) { this.listeners[type] = listener; }
    focus() { doc.activeElement = this; }
    fire(type, event = {}) { this.listeners[type](event); }
  }
  const ids = Object.fromEntries(["board", "status", "level", "sound", "focus"].map(id => [id, new Element()]));
  const buttons = ["up", "down", "left", "right", "wait", "undo", "restart"].map(action => {
    const element = new Element(); element.dataset.action = action; return element;
  });
  doc = {
    defaultView: {}, activeElement: null,
    getElementById: id => ids[id],
    createElement: () => new Element(),
    createDocumentFragment: () => new Element(),
    querySelectorAll: selector => { assert.equal(selector, "[data-action]"); return buttons; }
  };
  const controller = game.mount(doc);
  assert.equal(ids.board.children.length, 63);
  assert.equal(ids.level.children.length, 3);
  ids.focus.fire("click"); assert.equal(doc.activeElement, ids.board);
  function key(keyName, extras = {}) {
    let prevented = false;
    ids.board.fire("keydown", {key: keyName, repeat: false, altKey: false, ctrlKey: false, metaKey: false, preventDefault: () => { prevented = true; }, ...extras});
    return prevented;
  }
  assert.equal(key("ArrowRight"), true); assert.equal(controller.state.x, 2);
  key("ArrowRight", {repeat: true}); assert.equal(controller.state.turn, 1);
  assert.equal(key("Tab"), false);
  assert.equal(key("r", {ctrlKey: true}), false); assert.equal(controller.state.turn, 1);
  buttons.find(button => button.dataset.action === "left").fire("click");
  assert.equal(controller.state.x, 1); assert.equal(controller.state.turn, 2);
  key("Backspace"); assert.equal(controller.state.x, 2); assert.equal(controller.state.turn, 1);
  const actionKeys = {up: "w", down: "s", left: "a", right: "d", wait: " "};
  game.levels.forEach((_, index) => {
    ids.level.value = String(index); ids.level.fire("change");
    assert.equal(controller.state.levelIndex, index); assert.equal(controller.undoCount, 0);
    solve(index).forEach(action => key(actionKeys[action]));
    assert.equal(controller.state.won, true);
    assert.match(ids.status.textContent, /Shift complete/);
    key("u"); assert.equal(controller.state.won, false);
    key("r"); assert.equal(controller.state.turn, 0); assert.equal(controller.state.delivered.length, 0);
  });
});
test("browser shell binds the real engine and only local assets", () => {
  const html = fs.readFileSync(path.join(testDirectory, "../game/index.html"), "utf8");
  assert.match(html, /script defer src="game\.js"/);
  assert.match(html, /id="board" tabindex="0"/);
  assert.match(html, /connect-src 'none'/);
  for (const match of html.matchAll(/(?:src|href)="([^"]+)"/g)) {
    assert.equal(/^(?:https?:)?\/\//.test(match[1]), false);
    assert.equal(fs.existsSync(path.resolve(testDirectory, "../game", match[1])), true);
  }
  assert.equal(/\b(?:fetch|XMLHttpRequest|WebSocket|localStorage|sessionStorage)\b/.test(source), false);
});
console.log(`${checks} game checks passed. Manual browser and player tests are not implied.`);
}()).catch(error => { console.error(error); process.exitCode = 1; });

"""Summarize original synthetic playtest records without writing or networking."""
import argparse
import csv
import json
from pathlib import Path
from statistics import mean

ROOT = Path(__file__).resolve().parents[1]


def summarize(rows):
    if not rows:
        raise ValueError("At least one synthetic session is required")
    ids = set()
    for row in rows:
        if row["classification"] != "SYNTHETIC" or row["session_id"] in ids:
            raise ValueError("Expected uniquely identified SYNTHETIC records")
        ids.add(row["session_id"])
        for field in ("completed", "bridge_stall", "discovered_undo"):
            if row[field] not in ("0", "1"):
                raise ValueError("Invalid binary observation")
        if int(row["actions"]) < 0 or not 1 <= int(row["confidence_1_to_5"]) <= 5:
            raise ValueError("Observation is outside its valid range")
    completed = [row for row in rows if row["completed"] == "1"]
    return {
        "classification": "SYNTHETIC",
        "records": len(rows),
        "completions": len(completed),
        "completion_fraction": len(completed) / len(rows),
        "bridge_stalls": sum(int(row["bridge_stall"]) for row in rows),
        "undo_discoveries": sum(int(row["discovered_undo"]) for row in rows),
        "mean_completed_actions": mean(int(row["actions"]) for row in completed) if completed else None,
        "mean_confidence": mean(int(row["confidence_1_to_5"]) for row in rows),
        "evidence_limit": "Authored exercise only; not observed research or market validation."
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()
    with (ROOT / "data/playtests.csv").open(encoding="utf-8", newline="") as handle:
        rows = list(csv.DictReader(handle))
    report = summarize(rows)
    if args.self_test:
        assert (report["records"], report["completions"], report["bridge_stalls"], report["undo_discoveries"]) == (8, 5, 5, 3)
        assert report["mean_completed_actions"] == 54.4
        for bad in ([], [rows[0], rows[0]], [{**rows[0], "classification": "OBSERVED"}], [{**rows[0], "completed": "2"}]):
            try:
                summarize(bad)
            except ValueError:
                continue
            raise AssertionError("Invalid data was accepted")
        print("PASS: synthetic baseline plus four invalid-input cases")
    else:
        print(json.dumps(report, indent=2, sort_keys=True, allow_nan=False))


if __name__ == "__main__":
    main()
